create type public.event_type as enum('open_play','tournament','league','clinic','other');create type public.event_status as enum('draft','published','registration_closed','in_progress','completed','canceled');create type public.registration_status as enum('confirmed','waitlisted','withdrawn','canceled');
create table public.events(id uuid primary key default gen_random_uuid(),club_id uuid not null references public.clubs on delete cascade,type public.event_type not null,name text not null,venue text not null,starts_at timestamptz not null,ends_at timestamptz not null,registration_opens_at timestamptz,registration_closes_at timestamptz,capacity integer not null check(capacity>0),formats text[] not null,record_class public.record_class not null,eligibility jsonb not null default '{}',status public.event_status not null default 'draft',join_code text not null unique default encode(extensions.gen_random_bytes(9),'hex'),version bigint not null default 1,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),check(ends_at>starts_at));
create index events_club_start_idx on public.events(club_id,starts_at desc);create trigger events_updated before update on public.events for each row execute function private.set_updated_at();
create table public.event_courts(id uuid primary key default gen_random_uuid(),event_id uuid not null references public.events on delete cascade,label text not null,status text not null default 'available',created_at timestamptz not null default now(),unique(event_id,label));
create table public.event_registrations(id uuid primary key default gen_random_uuid(),event_id uuid not null references public.events on delete cascade,player_id uuid not null references public.players,status public.registration_status not null,waitlist_position bigint,terms_version text not null,registered_at timestamptz not null default now(),withdrawn_at timestamptz,version bigint not null default 1);
create unique index event_registrations_one_active_idx on public.event_registrations(event_id,player_id) where status in('confirmed','waitlisted');create unique index event_waitlist_position_idx on public.event_registrations(event_id,waitlist_position) where status='waitlisted';
create table public.event_attendance(id uuid primary key default gen_random_uuid(),event_id uuid not null references public.events on delete cascade,player_id uuid not null references public.players,state text not null default 'not_checked_in',updated_at timestamptz not null default now(),version bigint not null default 1,unique(event_id,player_id));
create table public.event_join_tokens(id uuid primary key default gen_random_uuid(),event_id uuid not null references public.events on delete cascade,token_hash text not null unique,expires_at timestamptz not null,revoked_at timestamptz,created_at timestamptz not null default now());
alter table public.events enable row level security;alter table public.event_courts enable row level security;alter table public.event_registrations enable row level security;alter table public.event_attendance enable row level security;alter table public.event_join_tokens enable row level security;
create policy published_events_read on public.events for select using(status<>'draft' or private.has_club_role(club_id,array['owner','organizer','staff']::public.club_role[]));create policy courts_event_read on public.event_courts for select using(exists(select 1 from public.events e where e.id=event_id and(e.status<>'draft' or private.has_club_role(e.club_id,array['owner','organizer','staff']::public.club_role[]))));create policy registration_own_read on public.event_registrations for select using(player_id=public.current_player_id() or exists(select 1 from public.events e where e.id=event_id and private.has_club_role(e.club_id,array['owner','organizer','staff']::public.club_role[])));
grant select on public.events,public.event_courts to anon,authenticated;grant select on public.event_registrations,public.event_attendance to authenticated;
